-- GENERATED by `wfj generate` from data/gossip/gossip-6a.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["6a0167c8dbe27e48"] = { "Grandi pericoli si celano oltre quelle mura, {name}. Torna indietro finché non avrai più esperienza nell'arte del combattimento.", "." },
  ["6a041fe17a8c9d95"] = { "Credi di poter venire qui a derubarci, eh!?", "." },
  ["6a077b276c4496ef"] = { "Con gli Imperatori uccisi, la protezione magica che blocca il teletrasporto all'interno del tempio si è molto indebolita. Se lo desideri, posso trasferirti nella tana degli Imperatori.", "." },
  ["6a0bce78c21d0e95"] = { "Per ora sto bene, non preoccuparti per me. Troverò il modo di uscire da qui dopo aver compiuto alcuni rituali di purificazione in questa stanza. Una magia immonda contamina questo luogo, {name}.", "." },
  ["6a0c65f68d69477e"] = { "Speriamo che i rinforzi da ⟦Stormwind=Roccavento⟧ arrivino presto. . . .", "." },
  ["6a0d7dadafdb3bae"] = { "Dov'è il ⟦Un'Goro Crater=Cratere di Un'Goro⟧?", "." },
  ["6a0db92916a30be6"] = { "Quassù ci si può annoiare, sai. Posso infastidire quel parruccone di Halaan solo fino a un certo punto, poi anche quello stanca.", "." },
  ["6a16ac0ae2a19de6"] = { "Finalmente! Sarò felice di andarmene da questo posto.", "." },
  ["6a256d9cfa307bd6"] = { "Mozzafiato. Bambini, quando torneremo a scuola, ognuno di voi farà una relazione orale su uno di questi personaggi leggendari.", "." },
  ["6a2a05c01bb0ef31"] = { "Molto bene. Allora tornerò.", "." },
  ["6a2bd00f5b6cd86b"] = { "Mi dispiace, ma non intendo vendere cavalli a chi non abbia raggiunto almeno il livello Osannato con il Regno di ⟦Stormwind=Roccavento⟧. Questi destrieri sono i migliori che troverai, e di certo non vogliamo che finiscano nelle mani dei nostri nemici.\n\nNon che io ti consideri un nemico, s'intende... guadagnati la fiducia di ⟦Stormwind=Roccavento⟧ e allora potremo fare affari.", "." },
  ["6a3a717bf51a87bf"] = { "Ahhh, cerchi ⟦Dungar Longdrink=Dungar Voloteso⟧. Ha alcuni dei grifoni più veloci da questa parte di Khaz Modan! Lo trovi sui bastioni, nel ⟦Trade District=Quartiere del Commercio⟧.", "." },
  ["6a3a78badaec92f7"] = { "Purtroppo qui al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ non c'è nessuno che insegni Sartoria, ma troverai un istruttore a ⟦Thunder Bluff=Picco del Tuono⟧. Segui il sentiero verso nord fuori dal villaggio finché non arrivi a degli ascensori. Prendine uno fino in cima all'altura e chiedi indicazioni a uno dei Guardiani del Picco.", "." },
  ["6a531fb832036eb0"] = { "%s ha FAME, TANTISSIMA FAME!", "." },
  ["6a5a6a771d66177d"] = { "Ce l'abbiamo fatta, <ragazzo/ragazza>! L'⟦Alliance=Alleanza⟧ e l'⟦Horde=Orda⟧ hanno finito di raccogliere tutto ciò che pensiamo ci servirà per la Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧. In questo momento le ultime merci vengono portate alla ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧, e arriveranno tutte entro un giorno. Dopodiché, <un/una> <eroe/eroina> <coraggioso/coraggiosa> dovrà suonare lo Scarab Gong con lo Scettro delle Sabbie Mutevoli per aprire i cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Quando quei cancelli si apriranno, la guerra avrà inizio!", "." },
  ["6a5aac8497250bcc"] = { "La maledizione finisce!", "." },
  ["6a6aa69d4766ddb8"] = { "Cerca Faruza. L'ultima volta che l'ho vista era davanti, tra le stalle e la casa all'estremità nord-ovest della città.", "." },
  ["6a6fb20d1921b65a"] = { "%s esce dal suo bozzolo sotto l'⟦Hive'Ashi=Alveare Ashi⟧.", "." },
  ["6a733a6c4e8937ca"] = { "Il maestro di battaglia", "." },
  ["6a76b473ee5e52c4"] = { "{name} attacca!", "." },
  ["6a7bc57783a09c2c"] = { "Salute, {class}. Mi occupo degli encomi per conto di Orgrimmar. È mio dovere assistere gli avventurieri che hanno ricevuto un Anello d'Encomio dell'⟦Horde=Orda⟧.\n\nAccetto anelli in quantità diverse, ma lo scambio più vantaggioso per te è consegnarne un gruppo di dieci alla volta. Quando consegnerai gli anelli, registrerò le tue gesta nei nostri archivi. Così otterrai il riconoscimento di Orgrimmar per il tuo impegno e il tuo servizio.", "." },
  ["6a8019341d73b343"] = { "Al'tabim, mi sa che ho perso il mio ⟦Zandalar Illusionist's Mantle=Coprispalle dell'Illusionista degli Zandalari⟧. Puoi darmene uno nuovo?", "." },
  ["6a85e90fa9bcd2b3"] = { "{class}, eh? Sono Krazek, il segretario del barone Revilgaz. So tutto di ciò che succede in questa giungla e oltre. Forse ti interesserebbe conoscere il prezzo corrente del petrolio a ⟦Ratchet=Porto Paranco⟧? No? Cerchi lavoro, magari? Lì posso aiutarti.", "." },
  ["6a8636ffa641a134"] = { "È un onore per me occuparmi delle forniture e delle provviste del Circolo della Terra. \r\n\nPer ora la mia merce è limitata, ma ripassa spesso: potrei avere nuovo equipaggiamento e nuove provviste da vendere.", "." },
  ["6a8e44d2e387b9d6"] = { "Hai fatto bene, {name}. Ti mostrerò come evocare un'ombra del Vuoto simile a quella che hai appena sconfitto.\n\nDevi sapere che abbiamo grandi aspettative su di te e che finora le hai soddisfatte.\n\nMa non montarti la testa, perché i compiti che ancora ti attendono faranno sembrare questo semplice come svegliarsi al mattino.", "." },
  ["6a9a03a79f85a082"] = { "Guarda qui, Malyfous.", "." },
  ["6aa2f2b00a3dd64e"] = { "Guarda dietro di te, {race}. L'alveare si agita mentre la terra intorno a noi trema e sussulta.\n\nÈ giunto il momento di mantenere una promessa che feci mille anni fa. Le sabbie si spostano ancora una volta, mentre i Qiraji preparano la guerra.", "." },
  ["6aa41add7fead851"] = { "Salute, {name}, e <benvenuto/benvenuta> a ⟦Camp Narache=Campo Narache⟧. La notizia del tuo arrivo si è sparsa in fretta nella tribù.", "." },
  ["6aa5abfc3294b017"] = { "Salute, {race}. Il materiale bellico viene inviato a poco a poco e dovrebbe essere alla ⟦Cenarion Hold=Fortezza Cenariana⟧ entro $2113w giorni. Possiamo solo sperare che, una volta arrivato, qualcuno che abbia ricomposto lo Scettro delle Sabbie Mutevoli si faccia avanti per suonare il gong e aprire le porte.", "." },
  ["6aa6ef0879b0c4b0"] = { "Hai fatto bene ad arrivare fin qui. Fai onore ai Windshaper, {name}.", "." },
  ["6abccdeaffcdf54b"] = { "Forse posso esserti d'aiuto. Ti propongo un patto, satiro. Recupererò questo pettorale grezzo e ucciderò la bestia, ⟦Goraluk Anvilcrack=Goraluk Spaccaroccia⟧. In cambio di questo compito, mi insegnerai a creare il pettorale.", "." },
  ["6abdbb975d05a696"] = { "Oggi avete distrutto ciò che mi è costato anni di lavoro! Per questo morirete tutti per mano mia!", "." },
  ["6ac04f21087aaefd"] = { "Dov'è l'istruttore di Alchimia?", "." },
  ["6ac8f298506b0909"] = { "La pelle, la gloriosa pelle. Tiene dentro... le tue interiora. Forse avrai notato che la mia pelle non se la passa tanto bene. Pensare che una volta mi preoccupavo dei pori. Ormai non mi resta quasi più pelle di cui preoccuparmi. In un certo senso, è molto liberatorio.", "." },
  ["6ad5ec419377290d"] = { "Riportami in vita.", "." },
  ["6ad8546fe7c37fa8"] = { "Tirth non è più lui, di questi tempi, e nemmeno il suo aiutante.", "." },
  ["6adac1bfdb09581e"] = { "Nostro occhio dice tu sembri <perso/persa>.", "." },
  ["6ae0fe469ee558a0"] = { "Senti il potere della Fratellanza!", "." },
  ["6ae33a6f62505abf"] = { "Voglio creare uno stemma di gilda.", "." },
  ["6af22cd3b4d8ea0f"] = { "La Bandiera dell'⟦Alliance=Alleanza⟧ è stata riportata alla sua base da {name}!", "." },
  ["6af9e0946435e937"] = { "*sospiro* ...113 gradi Kraklenheit. Non sai fare di meglio?", "." },
})
